package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/notification-service/internal/store"
)

// NewRouter wires the public HTTP surface. The README describes the error shape
// every entry must keep.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	deliveryRecords := "/api/v1/delivery-records"
	router.POST(deliveryRecords, createDeliveryRecord(st))
	router.POST(deliveryRecords+"/batch", createDeliveryRecords(st))
	router.GET(deliveryRecords, listDeliveryRecords(st))
	router.GET(deliveryRecords+"/search", searchDeliveryRecords(st))
	router.GET(deliveryRecords+"/failure-summary", failureSummary(st))
	router.GET(deliveryRecords+"/attempt-overview", attemptOverview(st))
	router.GET(deliveryRecords+"/trend", deliveryTrend(st))
	router.GET(deliveryRecords+"/channel-comparison", channelComparison(st))
	router.GET(deliveryRecords+"/:id", getDeliveryRecord(st))

	notifications := "/api/v1/notifications"
	router.GET(notifications+"/:notification_id/delivery-history", notificationDeliveryHistory(st))

	notificationTemplates := "/api/v1/notification-templates"
	router.POST(notificationTemplates, createNotificationTemplate(st))
	router.GET(notificationTemplates, listNotificationTemplates(st))
	router.GET(notificationTemplates+"/:template_id", getNotificationTemplate(st))

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}
package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/notification-service/internal/delivery"
	"github.com/luwa07832/notification-service/internal/store"
)

const codeInvalidSearch = "INVALID_DELIVERY_SEARCH"

// searchDeliveryRecords handles GET /api/v1/delivery-records/search. The
// channel and half-open time range keep the same meaning as the basic list
// entry; the remaining conditions narrow the search for failure tracking.
func searchDeliveryRecords(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		input := delivery.SearchInput{
			Channel: c.Query("channel"),
			Start:   c.Query("start"),
			End:     c.Query("end"),
		}
		if value, ok := c.GetQuery("template_id"); ok {
			input.TemplateID = &value
		}
		if value, ok := c.GetQuery("status"); ok {
			input.Status = &value
		}
		if value, ok := c.GetQuery("retry_min"); ok {
			input.RetryMin = &value
		}
		if value, ok := c.GetQuery("retry_max"); ok {
			input.RetryMax = &value
		}
		if value, ok := c.GetQuery("failure_reason_contains"); ok {
			input.FailureReasonContain = &value
		}
		if value, ok := c.GetQuery("page"); ok {
			input.Page = &value
		}
		if value, ok := c.GetQuery("page_size"); ok {
			input.PageSize = &value
		}

		query, err := delivery.NewSearch(input)
		if err != nil {
			respondError(c, http.StatusBadRequest, codeInvalidSearch, "delivery search parameters are not valid")
			return
		}

		result, err := st.SearchDeliveryRecords(c.Request.Context(), query)
		if err != nil {
			respondError(c, http.StatusServiceUnavailable, codeStorageDown, "delivery record storage is not available")
			return
		}
		c.JSON(http.StatusOK, gin.H{
			"records": result.Records,
			"pagination": gin.H{
				"page":      query.Page,
				"page_size": query.PageSize,
				"total":     result.Total,
			},
		})
	}
}

